-- Estúdio de Canal IA — esquema Neon Postgres
-- Aplicado inicialmente no projeto Neon `estudio-canal-ia` em 2026-10-13.
-- Toda chave, token ou segredo pertence ao cofre do ambiente e nunca a esta migração.

CREATE TABLE IF NOT EXISTS channels (id BIGSERIAL PRIMARY KEY, name TEXT NOT NULL, platform TEXT NOT NULL, external_channel_id TEXT, status TEXT NOT NULL DEFAULT 'not_connected', token_ref TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS trend_sources (id BIGSERIAL PRIMARY KEY, type TEXT NOT NULL, config JSONB NOT NULL DEFAULT '{}'::jsonb, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS trends (id BIGSERIAL PRIMARY KEY, source_id BIGINT REFERENCES trend_sources(id), title TEXT NOT NULL, url TEXT, score NUMERIC(7,2) NOT NULL DEFAULT 0, growth NUMERIC(7,2) NOT NULL DEFAULT 0, rationale TEXT, collected_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), status TEXT NOT NULL DEFAULT 'new');
CREATE TABLE IF NOT EXISTS ideas (id BIGSERIAL PRIMARY KEY, trend_id BIGINT REFERENCES trends(id), origin TEXT NOT NULL, title TEXT NOT NULL, format TEXT NOT NULL, angle TEXT, audience TEXT, keywords JSONB NOT NULL DEFAULT '[]'::jsonb, status TEXT NOT NULL DEFAULT 'idea', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS scripts (id BIGSERIAL PRIMARY KEY, idea_id BIGINT REFERENCES ideas(id), version INTEGER NOT NULL DEFAULT 1, content TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', approved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS assets (id BIGSERIAL PRIMARY KEY, script_id BIGINT REFERENCES scripts(id), type TEXT NOT NULL, uri TEXT, license TEXT, source TEXT, cost NUMERIC(10,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS videos (id BIGSERIAL PRIMARY KEY, script_id BIGINT REFERENCES scripts(id), format TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'assets', final_uri TEXT, duration_seconds INTEGER, qa_result JSONB NOT NULL DEFAULT '{}'::jsonb, synthetic BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS render_jobs (id BIGSERIAL PRIMARY KEY, video_id BIGINT REFERENCES videos(id), status TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, error TEXT, started_at TIMESTAMPTZ, finished_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS reviews (id BIGSERIAL PRIMARY KEY, target_type TEXT NOT NULL, target_id BIGINT NOT NULL, gate INTEGER NOT NULL CHECK (gate IN (1, 2)), decision TEXT NOT NULL, comment TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS publications (id BIGSERIAL PRIMARY KEY, video_id BIGINT REFERENCES videos(id), platform TEXT NOT NULL, external_video_id TEXT, scheduled_for TIMESTAMPTZ, published_at TIMESTAMPTZ, synthetic BOOLEAN NOT NULL DEFAULT FALSE, status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS lives (id BIGSERIAL PRIMARY KEY, type TEXT NOT NULL, scheduled_for TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'draft', notes TEXT);
CREATE TABLE IF NOT EXISTS analytics_snapshots (id BIGSERIAL PRIMARY KEY, publication_id BIGINT REFERENCES publications(id), snapshot_date DATE NOT NULL, views INTEGER NOT NULL DEFAULT 0, retention NUMERIC(5,2), ctr NUMERIC(5,2), subscribers INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS adapters (id BIGSERIAL PRIMARY KEY, capability TEXT NOT NULL, provider TEXT NOT NULL, plan TEXT NOT NULL DEFAULT 'free', active BOOLEAN NOT NULL DEFAULT FALSE, priority INTEGER NOT NULL DEFAULT 1, config JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS quota_log (id BIGSERIAL PRIMARY KEY, api TEXT NOT NULL, units INTEGER NOT NULL, recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_log (id BIGSERIAL PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, details JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS llm_usage_log (id BIGSERIAL PRIMARY KEY, provider TEXT NOT NULL, task TEXT NOT NULL, outcome TEXT NOT NULL, reason TEXT NOT NULL, latency_ms INTEGER NOT NULL DEFAULT 0, input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS llm_usage_log_created_at_idx ON llm_usage_log (created_at);
CREATE TABLE IF NOT EXISTS rate_limit_state (key TEXT PRIMARY KEY, window_started TIMESTAMPTZ NOT NULL DEFAULT NOW(), calls INTEGER NOT NULL DEFAULT 0, failed_attempts INTEGER NOT NULL DEFAULT 0, blocked_until TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS agent_confirmations (id UUID PRIMARY KEY, action TEXT NOT NULL, payload JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), resolved_at TIMESTAMPTZ);
